"use client";
/* Kitty, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Kitty(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("kitty"); }, []);
  return React.createElement("piix-pal", { "pal": "kitty", ...piixAttrs(props) });
}

export default Kitty;
